class T(unittest.TestCase):
    def test_case(self):
        def countdown(t):
            while t > 0:
                got = yield t
                t = (got if isinstance(got, int) else t) - 1
            return 'zero'
        it = countdown(3)
        seq = []
        seq.append(next(it))
        while len(seq) < 3:
            seq.append(it.send(seq[-1]))
        def finish():
            try:
                it.send(seq[-1])
            except StopIteration as e:
                seq.append(e.value)
        finish()
        self.assertEqual(seq == [3, 2, 1, 'zero'], True)

